//! The Rust tag taxonomy must give what the Python original gives. The cases are generated by `tools/parity/gen_taxonomy_vectors.py`.

use ax_core::tag_taxonomy::{build_tag_taxonomy, categories_for_tag, is_generic_tag, normalize_tag_key, TagRow};
use serde_json::Value;

fn cases() -> Value {
    serde_json::from_str(include_str!("tag_taxonomy_cases.json")).unwrap()
}

#[test]
fn search_words_are_split_like_python() {
    let cases = cases();
    let all = cases["tokens"].as_object().unwrap();
    assert!(all.len() > 20);
    for (text, expected) in all {
        let want: Vec<&str> = expected.as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect();
        assert_eq!(ax_core::text::word_tokens(text, 8), want, "{text:?}");
    }
}

#[test]
fn keys_are_normalised_like_python() {
    let cases = cases();
    for (name, expected) in cases["normalize"].as_object().unwrap() {
        assert_eq!(normalize_tag_key(name), expected.as_str().unwrap(), "{name:?}");
    }
}

#[test]
fn generic_tags_match_python() {
    for (name, expected) in cases()["generic"].as_object().unwrap() {
        assert_eq!(is_generic_tag(name), expected.as_bool().unwrap(), "{name:?}");
    }
}

#[test]
fn categories_match_python() {
    for (name, expected) in cases()["categories"].as_object().unwrap() {
        let want: Vec<&str> = expected.as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect();
        assert_eq!(categories_for_tag(name), want, "{name:?}");
    }
}

#[test]
fn the_taxonomy_matches_python_case_by_case() {
    let cases = cases();
    let all = cases["taxonomy"].as_array().unwrap();
    assert!(all.len() > 10);
    for (i, case) in all.iter().enumerate() {
        let rows: Vec<TagRow> = case["rows"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| TagRow { name: r["name"].as_str().unwrap().to_string(), video_id: r["video_id"].as_i64(), video_count: r["video_count"].as_i64().unwrap() })
            .collect();
        let got = build_tag_taxonomy(case["total"].as_i64().unwrap(), &rows);
        assert_eq!(got, case["expected"], "case {i} (total {})", case["total"]);
        // the order of the ranked list and of the map is part of the answer too
        let ranked = |v: &Value| v["ranked_tags"].as_array().unwrap().iter().map(|t| t["key"].as_str().unwrap().to_string()).collect::<Vec<_>>();
        assert_eq!(ranked(&got), ranked(&case["expected"]), "ranked order, case {i}");
        let keys = |v: &Value| v["tag_map"].as_object().unwrap().keys().cloned().collect::<Vec<_>>();
        assert_eq!(keys(&got), keys(&case["expected"]), "map order, case {i}");
    }
}
